#!/usr/bin/env python3
"""Execute the autonomous Pocket PSRAM probe against independent chip pins."""
import json
from pathlib import Path
import shutil
import subprocess
import tempfile

from prepare_psram_burst import prepare, UPSTREAM
from prepare_resource_targets import digest
from tool_paths import ROOT, find_tool


def bench_text():
    # Reuse only the established clock/PHY/pad-delay wiring. Host stimulus and
    # expected bytes are generated by the actual deployable autonomous probe.
    text=(ROOT/'sim/memory/tb_psx_psram_burst.sv').read_text().split('    function automatic integer slot',1)[0]
    text=text.replace('module tb_psx_psram_burst;', 'module tb_psx_psram_probe;\n    parameter integer FAULT_KIND=0;')
    for before,after in [
        ('reg valid=0,write=0,last=0,die=0;', 'wire valid,write,last,die;'),
        ('reg [21:0] address=0;', 'wire [21:0] address;'),
        ('reg [31:0] data=0;', 'wire [31:0] data;'),
        ('reg [3:0] mask=0;', 'wire [3:0] mask;'),
        ('.z_die(die)', '.z_die(die && FAULT_KIND!=2)'),
    ]:
        if text.count(before)!=1: raise ValueError('Pin fixture contract changed: '+before)
        text=text.replace(before,after)
    return text+'''
    wire passed,failed,checking;
    wire [17:0] checked;
    wire [22:0] failed_addr;
    wire [31:0] failed_expected,failed_actual;
    psx_psram_probe probe (.clk(clk),.reset(rst),.initialized(initialized),.wait_error(wait_error),
        .valid(valid),.write(write),.die(die),.last(last),.address(address),.wdata(data),.byte_en(mask),
        .ready(ready),.rvalid(rvalid),.idle(idle),.rdata(read_data ^ (FAULT_KIND==1 ? 32'b1 : 32'b0)),
        .passed(passed),.failed(failed),.checking(checking),.checked_words(checked),
        .failed_address(failed_addr),.failed_expected(failed_expected),.failed_actual(failed_actual));
    integer reads=0,writes=0;
    always @(posedge clk) if(!rst && valid && ready) begin
        if(write) writes=writes+1;else reads=reads+1;
    end
    always @(negedge clk) if(failed)
        $fatal(1,"PSRAM_PROBE mismatch address=%h expected=%h actual=%h",failed_addr,failed_expected,failed_actual);
    task automatic complete;
        begin
            while(!passed) @(negedge clk);
            if(checked!=16384 || reads!=16384 || writes!=32768 || checking)
                $fatal(1,"Probe coverage/count mismatch");
            while(!idle) @(negedge clk);
            $display("PSRAM_PROBE PASS checked_words=%0d read_bytes=%0d host_reads=%0d host_writes=%0d physical_reads=%0d physical_writes=%0d configs=%0d",
                checked,4*checked,reads,writes,chip0.reads,chip0.writes,chip0.config_writes);
        end
    endtask
    initial begin
        repeat(4) @(negedge clk);rst=0;complete();
        // Warm reset preserves physical RAM and reinitializes/test-overwrites
        // both dies. The prior run's status must clear and independently pass.
        rst=1;reads=0;writes=0;repeat(4) @(negedge clk);rst=0;complete();$finish;
    end
    initial begin #20000000;$fatal(1,"PSRAM probe watchdog");end
endmodule
'''


def main():
    compiler,runtime=find_tool('iverilog'),find_tool('vvp')
    if not compiler or not runtime: raise SystemExit('Icarus Verilog required')
    parent=ROOT/'build/sim/psram-probe';parent.mkdir(parents=True,exist_ok=True)
    work=Path(tempfile.mkdtemp(prefix='checks-',dir=parent));controller=prepare(work/'rtl')
    # The generate's unselected original-PHY branch requires no module source.
    bench=work/'tb_psx_psram_probe.sv';bench.write_text(bench_text())
    sources=[Path(controller['path']),ROOT/'rtl/pocket/psx_psram_probe.sv',
        ROOT/'sim/memory/altddio_registered_model.sv',ROOT/'sim/memory/cellularram_burst_model.sv',bench]
    protected={str(p):digest(p) for p in [*sources,UPSTREAM,Path(__file__),ROOT/'scripts/prepare_psram_burst.py',
                                        ROOT/'sim/memory/tb_psx_psram_burst.sv']}
    archive=[]
    for i,(path,sha) in enumerate(protected.items()):
        target=work/'compiled-inputs'/str(i)/Path(path).name;target.parent.mkdir(parents=True,exist_ok=True)
        shutil.copyfile(path,target);archive.append(dict(original=path,path=str(target),sha256=sha))
    results=[]
    for name,params,should_pass in [('nominal',{},True),
        ('delayed',dict(CLOCK_DELAY=4,CONTROL_DELAY=3,RETURN_DELAY=.5),True),
        ('read_corruption',dict(FAULT_KIND=1),False),('die_alias',dict(FAULT_KIND=2),False)]:
        binary=work/(name+'.vvp')
        with (work/(name+'-build.log')).open('w') as log:
            subprocess.run([compiler,'-g2012','-s','tb_psx_psram_probe',
                *[f'-Ptb_psx_psram_probe.{p}={v}' for p,v in params.items()],'-o',str(binary),
                *map(str,sources)],stdout=log,stderr=subprocess.STDOUT,check=True,timeout=60)
        result=subprocess.run([runtime,str(binary)],capture_output=True,text=True,timeout=120)
        output=result.stdout+result.stderr;(work/(name+'.log')).write_text(output);print(output,flush=True)
        if should_pass:
            if result.returncode or output.count('PSRAM_PROBE PASS')!=2:
                raise SystemExit('Autonomous probe failed; preserve '+str(work))
        elif not result.returncode or 'PSRAM_PROBE mismatch' not in output:
            raise SystemExit('Fault not detected: '+name+'; preserve '+str(work))
        results.append(dict(name=name,parameters=params,expected_pass=should_pass,exit_code=result.returncode,
                            log_sha256=digest(work/(name+'.log'))))
    for p,sha in protected.items():
        if digest(Path(p))!=sha: raise ValueError('Compiled probe input changed: '+p)
    (work/'report.json').write_text(json.dumps(dict(controller=controller,results=results,
        protected_sha256=protected,compiled_input_archive=archive,hardware_verified=False),indent=2)+'\n')
    print(work)


if __name__=='__main__':main()
